use derive_setters :: Setters ; use forge_domain :: { McpServers , ToolDefinition } ; use serde :: { Deserialize , Serialize } ; impl ToolsOverview { # [doc = " Create a new empty ToolsOverview"] pub fn new () -> Self { ToolsOverview :: default () } pub fn as_vec (& self) -> Vec < & ToolDefinition > { let mut tools = Vec :: new () ; tools . extend (& self . system) ; tools . extend (& self . agents) ; for server_tools in self . mcp . get_servers () . values () { tools . extend (server_tools) ; } tools } }